#[cfg(test)]
mod tests {
    use super::*;

    /// The widths of every entry are the differences of its (ISO 14496-3) offsets.
    #[test]
    fn sfb_widths_are_offset_differences() {
        for e in &SFB_INFO_1024 {
            for (widths, offsets) in [(e.long_widths, e.long_offsets), (e.short_widths, e.short_offsets)] {
                assert_eq!(widths.len() + 1, offsets.len());
                assert!(widths.iter().zip(offsets.windows(2)).all(|(&w, o)| w == o[1] - o[0]), "rate {}", e.rate);
            }
        }
    }
}
